// A1–A2 and B1: student-facing interface texts matched to the level (all texts are student-facing)
const ui=()=>{const c=CONTENT[lang];if(ORDER.indexOf(level)<2&&c.uiSimple)return {...c.ui,...c.uiSimple};if(level==='B1'&&c.uiB1)return {...c.ui,...c.uiB1};return c.ui;};
const data=()=>CONTENT[lang].levels[level];
function setText(id,value){const n=$(id),s=String(value);if(n.textContent!==s)n.textContent=s;}
function setButtonText(id,value){setText(id,value);}
function savePrefs(){try{localStorage.setItem(STORAGE,JSON.stringify({lang,level,theme,current}));}catch(_){}clbNotify({lessonId:"artificial-intelligence",language:lang,cefr:level,stationId:'s0'+(current+1)});}
function loadPrefs(){try{const x=JSON.parse(localStorage.getItem(STORAGE)||'{}');if(CONTENT[x.lang])lang=x.lang;if(ORDER.includes(x.level))level=x.level;if(['light','dark'].includes(x.theme))theme=x.theme;if(Number.isInteger(x.current)&&x.current>=0&&x.current<8)current=x.current;}catch(_){}}
function make(tag,cls,txt){const e=document.createElement(tag);if(cls)e.className=cls;if(txt!==undefined)e.textContent=txt;return e;}
function replaceChildren(id,items){$(id).replaceChildren(...items);}
function toggleDetails(name,open){const panel=$(name+'Reveal'),button=$(name+'Btn');panel.hidden=!open;button.setAttribute('aria-expanded',String(open));const u=ui();setText(name+'Btn',u[name+(open?'Hide':'Show')]);}
function refreshDetails(){for(const name of ['support','challenge','stretch'])toggleDetails(name,false);}
function renderStation(){
 const u=ui(),s=data().stations[current];
 setText('stationNum',current+1);setText('stationEyebrow',`${u.station} ${current+1} / 8`);
 setText('stationTitle',s.title);setText('stationSubtitle',s.subtitle);
 setText('mainLabel',u.main);setText('mainQuestion',s.main);setText('questionsLabel',u.questions);
 replaceChildren('questions',s.questions.map((q,i)=>{const e=make('div','question');e.append(make('span','qnum',i+1),make('span','',q));return e}));
 for(const name of ['support','challenge','stretch']){setText(name+'Title',u[name+'Title']);setText(name+'Desc',u[name+'Desc']);}
 replaceChildren('supportList',s.support.map(t=>make('li','',t)));
 setText('challengeReveal',s.challenge);setText('stretchReveal',s.stretch);
 refreshDetails();
 setText('progressText',`${u.station} ${current+1} ${u.of} 8 · ${u.progress}`);
 setText('previousBtn',`← ${u.previous}`);setText('nextBtn',current===7?u.stay:`${u.next} →`);
 $('previousBtn').disabled=current===0;$('nextBtn').disabled=current===7;
 mountTimer();
}
function renderNav(){
 const u=ui();replaceChildren('sectionNav',data().stations.map((s,i)=>{
  const b=make('button',i===current?'active':'',`${i+1}. ${s.title}`);
  b.type='button';b.setAttribute('aria-current',i===current?'step':'false');b.addEventListener('click',()=>goTo(i));return b;
 }));
}
function renderResources(){
 const u=ui();setText('vocabLabel',u.vocabLabel);setText('vocabHeading',u.vocabLabel);setText('vocabDesc',u.vocabDesc);
 replaceChildren('vocabGrid',data().vocab.map(([word,desc])=>{const el=make('div','vocab-item');el.append(make('b','',word),make('span','',desc));return el;}));
 setText('toolkitLabel',u.toolkitLabel);setText('toolkitHeading',u.toolkitLabel);setText('toolkitDesc',u.toolkitDesc);
 replaceChildren('toolkitGrid',data().toolkit.map(([name,desc])=>{const el=make('div','vocab-item');el.append(make('b','',name),make('span','',desc));return el;}));
 setText('lessonTipLabel',`${u.tipLabel}${lang==='fr'?'\u202f:':':'}`);setText('lessonTipText',u['tip'+level]);
 setText('footerCredit',`${u.format} · ${u.changeLevel} ${level} · 8 ${lang==='de'?u.stations:u.stations.toLocaleLowerCase(lang)} · ${u.offline}`);
}
function renderHeader(){
 const u=ui();document.documentElement.lang=lang;
 document.title=`${u.title} | ${u.brand} · ${level}`;$('sectionNav').setAttribute('aria-label',u.stationNavAria);document.querySelector('.topbar').setAttribute('aria-label',u.controlsAria);
 $('languageSelect').value=lang;setText('languageLabel',u.changeLanguage);$('languageSelect').setAttribute('aria-label',u.changeLanguage);
 setText('levelLabel',u.changeLevel);$('levelSwitch').setAttribute('aria-label',u.changeLevel);
 document.querySelectorAll('[data-level]').forEach(b=>{b.classList.toggle('active',b.dataset.level===level);b.setAttribute('aria-pressed',String(b.dataset.level===level));});
 setText('brandTitle',u.title);setText('brandSubtitle',`${u.subbrand} · ${level}`);
 setText('kicker',u.eyebrow);setText('heroTitle',u.title);setText('heroStrap',u.strap);setText('heroIntro',u.hero);setText('privacyNotice',u.privacy);setText('startLessonBtn',u.startLesson);
 setText('metaLevel',`${u.changeLevel}${lang==='fr'?'\u202f:':':'} ${level}`);setText('metaFormat',u.format);setText('metaTime',u.estimated);
 setText('goalLabel',u.levelGoal);setText('goalText',u['goal'+level]);
 replaceChildren('quickstart',[u.step1,u.step2,u.step3,u.step4].map((t,i)=>{const el=make('div','quickstep');el.append(make('b','',`0${i+1}`),make('span','',t));return el;}));
 setText('warmTitle',u.warmTitle);setText('warmTime',u.warmTime);setText('warmHint',u.warmHint);setText('warmTask',data().warm);
 setText('navHeading',u.stations);setText('formatHint',u.formatHint);
 function updateIconButton(id,symbol,label){const b=$(id);b.replaceChildren(document.createTextNode(symbol+' '),make('span','small-hide',label));}
 updateIconButton('themeBtn',theme==='dark'?'☀':'☾',theme==='dark'?u.themeDay:u.themeNight);
 updateIconButton('resetBtn','↺',u.resetLesson);
 $('themeBtn').title=theme==='dark'?u.themeDay:u.themeNight;$('resetBtn').title=u.resetLesson;
 updateFullscreenButton();updateTimerTranslations();
}
function renderAll(){renderHeader();renderNav();renderStation();renderResources();initLookups();savePrefs();refreshTimer();}
function goTo(i,{scroll=true}={}){if(i<0||i>7)return;hideLookup();current=i;closeEditor();if(mobileTimerQuery.matches)setFloatingExpanded(false);renderNav();renderStation();savePrefs();if(scroll){requestAnimationFrame(()=>{$('station').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});const nav=$('sectionNav'),chosen=nav.children[current];if(chosen){const a=chosen.getBoundingClientRect(),n=nav.getBoundingClientRect();nav.scrollTo({left:nav.scrollLeft+a.left-n.left-(nav.clientWidth-a.width)/2,behavior:'smooth'});}});}}
function switchVariant(newLang,newLevel){
 if(!CONTENT[newLang]||!ORDER.includes(newLevel))return;
 // Keep station and the single countdown alive. The warm-up starts collapsed on every load.
 hideLookup();lang=newLang;level=newLevel;closeEditor();renderAll();
}
function applyTheme(){document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#07111f':'#eef4fa';}

// Native fullscreen is preferred. iOS phones and blocked iframes get a focus-mode fallback.
let lessonFocusScrollY=0;
const FOCUS_LABEL={en:'Focus mode',es:'Modo concentración',de:'Fokusmodus',fr:'Mode concentration'};
const FOCUS_EXIT={en:'Exit focus mode',es:'Salir del modo concentración',de:'Fokusmodus beenden',fr:'Quitter le mode concentration'};
const IN_FRAME=(()=>{try{return window.self!==window.top}catch(_){return true}})();
const FOCUS_NOTICE={
 en:'Focus mode: the browser bars can stay visible.',
 es:'Modo concentración: las barras del navegador pueden seguir visibles.',
 de:'Fokusmodus: Browserleisten können sichtbar bleiben.',
 fr:'Mode concentration : les barres du navigateur peuvent rester visibles.'
};
const fsElement=()=>document.fullscreenElement||document.webkitFullscreenElement||null;
function fsSupported(){
 const root=document.documentElement;
 if(!(typeof root.requestFullscreen==='function'||typeof root.webkitRequestFullscreen==='function'))return false;
 if(document.fullscreenEnabled===false&&document.webkitFullscreenEnabled!==true)return false;
 if(document.permissionsPolicy?.allowsFeature?.('fullscreen')===false)return false;
 if(document.featurePolicy?.allowsFeature?.('fullscreen')===false)return false;
 return true;
}
function enterFocus(){
 if(document.documentElement.classList.contains('lesson-focus'))return;
 lessonFocusScrollY=window.scrollY;
 document.documentElement.classList.add('lesson-focus');
 document.querySelector('.app').scrollTop=lessonFocusScrollY;
 updateFullscreenButton();showToast(FOCUS_NOTICE[lang]||FOCUS_NOTICE.en);
}
function exitFocus(){
 if(!document.documentElement.classList.contains('lesson-focus'))return;
 const y=document.querySelector('.app').scrollTop;
 document.documentElement.classList.remove('lesson-focus');
 lessonFocusScrollY=y;
 window.requestAnimationFrame(()=>window.scrollTo({top:lessonFocusScrollY,behavior:'instant'}));
 updateFullscreenButton();
}
function updateFullscreenButton(){
 const inFocus=document.documentElement.classList.contains('lesson-focus');
 const yes=!!fsElement()||inFocus;
 const button=$('fullBtn');
 // Inside AI Studio (iframe without fullscreen permission) the Studio viewer owns full screen: no second control.
 button.hidden=!yes&&!fsSupported()&&IN_FRAME;
 const text=inFocus?(FOCUS_EXIT[lang]||FOCUS_EXIT.en):yes?ui().exitFullscreen:(fsSupported()?ui().fullscreen:FOCUS_LABEL[lang]);
 button.replaceChildren(document.createTextNode((yes?'⤢':'⛶')+' '),make('span','small-hide',text));
 button.title=text;button.setAttribute('aria-label',text);button.setAttribute('aria-pressed',String(yes));
}
async function toggleFullscreen(){
 const d=document,root=d.documentElement;
 if(root.classList.contains('lesson-focus')){exitFocus();return;}
 if(fsElement()){
  try{if(d.exitFullscreen)await d.exitFullscreen();else if(d.webkitExitFullscreen)await d.webkitExitFullscreen();}
  catch(_){showToast(ui().fullError);}finally{updateFullscreenButton();}
  return;
 }
 if(fsSupported()){
  try{
   const result=typeof root.requestFullscreen==='function'?root.requestFullscreen():root.webkitRequestFullscreen();
   if(result&&typeof result.then==='function')await result;
   else await new Promise(resolve=>setTimeout(resolve,350));
   if(fsElement()){updateFullscreenButton();return;}
  }catch(_){/* Some Safari versions and sandboxed iframes reject the request. */}
 }
 enterFocus();
}


